record.field:
service = env.ref('l10n_ro_anaf_token_online.iap_online_service_anaf_token')
if not service.x_token:
    action = env.ref('deltatech_iap_online.action_iap_online_activate').with_context(
        active_model='x_iap_online_service', active_id=service.id, active_ids=service.ids,
    ).run()
else:
    hook = env.ref('l10n_ro_anaf_token_online.automation_anaf_token_receive').url
    # URL-encoded by hand: no urllib in the server actions
    for char, code in [('%', '%25'), (':', '%3A'), ('/', '%2F'), ('?', '%3F'), ('&', '%26'), ('=', '%3D'), ('#', '%23'), ('+', '%2B'), (' ', '%20')]:
        hook = hook.replace(char, code)
    action = {
        'type': 'ir.actions.act_url',
        'target': 'new',
        'url': '%s/iap_anaf/authorize/%s?hook=%s' % (service.x_server.rstrip('/'), service.x_token, hook),
    }
